import KnittingInstructionActualizer, { StitchRow, KnittingInstruction, CableCrossEvent } from './KnittingInstructionActualizer';

/**
 * HandKnittingActualizer - Generates instructions for hand knitting
 * 
 * Specializes the generic actualizer for traditional hand knitting:
 * - Shows individual row increases/decreases  
 * - Includes wrap/turn instructions for short rows
 * - Uses hand knitting terminology and conventions
 * - Supports different short row techniques (wraps, gaps, german)
 * - Generates cable crossing instructions
 */
export class HandKnittingActualizer extends KnittingInstructionActualizer {
    /**
     * Convert stitch plan section to hand knitting instructions
     * 
     * @param sectionRows - Array of rows for this section
     * @param baseRowIndex - Starting row index for this section
     * @param isSuccessor - Whether this section is a successor trapezoid (should be consolidated)
     */
    actualize(sectionRows: StitchRow[], baseRowIndex: number, isSuccessor: boolean = false): KnittingInstruction[] {
        const instructions: KnittingInstruction[] = [];

        if (sectionRows.length === 0) return instructions;

        // If this is a successor trapezoid with shaping, consolidate into a single step
        if (isSuccessor && sectionRows.length > 0) {
            const firstRow = sectionRows[0];
            const lastRow = sectionRows[sectionRows.length - 1];
            const firstStitches = firstRow.leftStitchesInWork + firstRow.rightStitchesInWork;
            const lastStitches = lastRow.leftStitchesInWork + lastRow.rightStitchesInWork;
            
            // Check if there's any shaping in this successor
            const hasShaping = firstStitches !== lastStitches;
            
            if (hasShaping) {
                // Consolidate entire successor into one step
                const leftChange = lastRow.leftStitchesInWork - firstRow.leftStitchesInWork;
                const rightChange = lastRow.rightStitchesInWork - firstRow.rightStitchesInWork;
                
                let instruction = `Section ${firstRow.sectionLabel || ''}: `;
                instruction += this.buildShapingText(leftChange, rightChange);
                instruction += `Knit ${sectionRows.length} rows. `;
                instruction += `(RC=${lastRow.rowNumber}, ${lastStitches} sts in work)`;
                
                // Generate row-by-row instructions for expandable view
                const rowInstructions: string[] = [];
                for (let k = 0; k < sectionRows.length; k++) {
                    const r = sectionRows[k];
                    const prevRow = k > 0 ? sectionRows[k - 1] : r;
                    const leftDiff = r.leftStitchesInWork - prevRow.leftStitchesInWork;
                    const rightDiff = r.rightStitchesInWork - prevRow.rightStitchesInWork;
                    
                    let rowText = `Row ${baseRowIndex + k + 1}: `;
                    if (leftDiff > 0) rowText += `Inc ${leftDiff} left, `;
                    else if (leftDiff < 0) rowText += `Dec ${-leftDiff} left, `;
                    if (rightDiff > 0) rowText += `Inc ${rightDiff} right, `;
                    else if (rightDiff < 0) rowText += `Dec ${-rightDiff} right, `;
                    rowText += `Knit across ${r.leftStitchesInWork + r.rightStitchesInWork} sts. (RC=${r.rowNumber})`;
                    
                    rowInstructions.push(rowText);
                }
                
                instructions.push({
                    text: instruction,
                    stepData: {
                        text: instruction,
                        startRowIndex: baseRowIndex,
                        endRowIndex: baseRowIndex + sectionRows.length - 1,
                        rowsInStep: sectionRows.length,
                        absolutePositioning: this.getAbsolutePosition(lastRow)
                    },
                    rows: rowInstructions
                });
                
                return instructions;
            }
        }

        let i = 0;
        while (i < sectionRows.length) {
            const row = sectionRows[i];

            // Check if this row is part of a short row sequence
            if (row.shortRowInfo) {
                // Check if there are multiple short row sections at the same base row
                const baseRow = row.shortRowInfo.baseRowNumber ?? row.rowNumber;
                const shortRowSectionsAtThisRow: number[] = [i]; // Start with current index
                
                // Look ahead to see if more short row sections share the same base row
                let j = i + row.shortRowInfo.totalRowsInShortRow;
                while (j < sectionRows.length) {
                    const nextRow = sectionRows[j];
                    if (!nextRow.shortRowInfo) break;
                    
                    const nextBaseRow = nextRow.shortRowInfo.baseRowNumber ?? nextRow.rowNumber;
                    if (nextBaseRow === baseRow) {
                        shortRowSectionsAtThisRow.push(j);
                        j += nextRow.shortRowInfo.totalRowsInShortRow;
                    } else {
                        break;
                    }
                }
                
                // Generate instructions for all short row sections at this base row
                this._generateShortRowInstructions(sectionRows, shortRowSectionsAtThisRow, baseRowIndex, instructions);
                
                // Skip all rows we just processed
                i = j;
            } else {
                // Regular (non-short-row) processing
                // Strategy: Group rows where the stitch count ENDS at the same value
                // Find the next row where stitch count changes, and include that row in this group
                
                const firstRow = row;
                const stepStartRowIndex = baseRowIndex + i;
                let j = i + 1;
                let foundChange = false;
                
                // Look for the row where stitch count changes
                while (j < sectionRows.length) {
                    const currentRow = sectionRows[j];
                    const prevRow = sectionRows[j - 1];
                    
                    // Stop at short rows
                    if (currentRow.shortRowInfo) {
                        break;
                    }
                    
                    // Check if stitch count changed from previous row
                    if (currentRow.leftStitchesInWork !== prevRow.leftStitchesInWork ||
                        currentRow.rightStitchesInWork !== prevRow.rightStitchesInWork) {
                        // This row has a change - include it and stop
                        j++;
                        foundChange = true;
                        break;
                    }
                    
                    j++;
                }
                
                const consecutiveRows = j - i;
                const lastRowInGroup = sectionRows[j - 1];
                const totalLeftDiff = lastRowInGroup.leftStitchesInWork - firstRow.leftStitchesInWork;
                const totalRightDiff = lastRowInGroup.rightStitchesInWork - firstRow.rightStitchesInWork;
                
                // Check if this is entire remaining section and rectangular
                const isRemainingRectangular = (j === sectionRows.length) && 
                    (totalLeftDiff === 0 && totalRightDiff === 0);
                
                if (isRemainingRectangular) {
                    // Entire remaining section is rectangular
                    const rectInstr = `Knit ${consecutiveRows} rows (RC=${lastRowInGroup.rowNumber}, ${lastRowInGroup.leftStitchesInWork + lastRowInGroup.rightStitchesInWork} sts in work).`;
                    
                    // Generate row-by-row instructions for expandable view
                    const rowInstructions: string[] = [];
                    for (let k = i; k < j; k++) {
                        const r = sectionRows[k];
                        rowInstructions.push(`Row ${baseRowIndex + k + 1}: Knit across ${r.leftStitchesInWork + r.rightStitchesInWork} stitches (${r.leftStitchesInWork} left, ${r.rightStitchesInWork} right). (RC=${r.rowNumber})`);
                    }
                    
                    instructions.push({
                        text: rectInstr,
                        stepData: {
                            text: rectInstr,
                            startRowIndex: stepStartRowIndex,
                            endRowIndex: baseRowIndex + j - 1,
                            rowsInStep: consecutiveRows,
                            absolutePositioning: this.getAbsolutePosition(lastRowInGroup)
                        },
                        rows: rowInstructions
                    });
                    i = j;
                } else if (totalLeftDiff !== 0 || totalRightDiff !== 0) {
                    // Build shaping instruction
                    let instruction = this.buildShapingText(totalLeftDiff, totalRightDiff);
                    instruction += `Knit ${consecutiveRows} rows. `;
                    instruction += `(RC=${lastRowInGroup.rowNumber}, ${lastRowInGroup.leftStitchesInWork + lastRowInGroup.rightStitchesInWork} sts in work)`;
                    
                    // Generate row-by-row instructions for expandable view
                    const rowInstructions: string[] = [];
                    for (let k = i; k < j; k++) {
                        const r = sectionRows[k];
                        const prevRow = k > i ? sectionRows[k - 1] : sectionRows[k];
                        const leftDiff = r.leftStitchesInWork - (k > i ? prevRow.leftStitchesInWork : r.leftStitchesInWork);
                        const rightDiff = r.rightStitchesInWork - (k > i ? prevRow.rightStitchesInWork : r.rightStitchesInWork);
                        
                        let rowText = `Row ${baseRowIndex + k + 1}: `;
                        if (leftDiff > 0) rowText += `Inc ${leftDiff} left, `;
                        else if (leftDiff < 0) rowText += `Dec ${-leftDiff} left, `;
                        if (rightDiff > 0) rowText += `Inc ${rightDiff} right, `;
                        else if (rightDiff < 0) rowText += `Dec ${-rightDiff} right, `;
                        rowText += `Knit across ${r.leftStitchesInWork + r.rightStitchesInWork} sts. (RC=${r.rowNumber})`;
                        
                        rowInstructions.push(rowText);
                    }
                    
                    instructions.push({
                        text: instruction,
                        stepData: {
                            text: instruction,
                            startRowIndex: stepStartRowIndex,
                            endRowIndex: baseRowIndex + j - 1,
                            rowsInStep: consecutiveRows,
                            absolutePositioning: this.getAbsolutePosition(lastRowInGroup)
                        },
                        rows: rowInstructions
                    });
                    i = j;
                } else {
                    // No shaping in this group (straight section)
                    const rectInstr = `Knit ${consecutiveRows} rows (RC=${lastRowInGroup.rowNumber}, ${lastRowInGroup.leftStitchesInWork + lastRowInGroup.rightStitchesInWork} sts in work).`;
                    
                    // Generate row-by-row instructions for expandable view
                    const rowInstructions: string[] = [];
                    for (let k = i; k < j; k++) {
                        const r = sectionRows[k];
                        rowInstructions.push(`Row ${baseRowIndex + k + 1}: Knit across ${r.leftStitchesInWork + r.rightStitchesInWork} stitches (${r.leftStitchesInWork} left, ${r.rightStitchesInWork} right). (RC=${r.rowNumber})`);
                    }
                    
                    instructions.push({
                        text: rectInstr,
                        stepData: {
                            text: rectInstr,
                            startRowIndex: stepStartRowIndex,
                            endRowIndex: baseRowIndex + j - 1,
                            rowsInStep: consecutiveRows,
                            absolutePositioning: this.getAbsolutePosition(lastRowInGroup)
                        },
                        rows: rowInstructions
                    });
                    i = j;
                }
            }
        }

        return instructions;
    }

    /**
     * Generate instructions for a short row sequence
     * Split into decrease phase and increase phase for better clarity
     */
    private _generateShortRowInstructions(sectionRows: StitchRow[], startIndices: number[], baseRowIndex: number, instructions: KnittingInstruction[]): void {
        if (startIndices.length === 0 || startIndices[0] >= sectionRows.length) return;

        // Handle multiple short row sections at the same base row (mirrored pairs)
        if (startIndices.length > 1) {
            this._generateMirroredShortRowInstructions(sectionRows, startIndices, baseRowIndex, instructions);
            return;
        }

        // Single short row section - split into decrease and increase phases
        const startIndex = startIndices[0];
        const firstShortRow = sectionRows[startIndex];
        const srInfo = firstShortRow.shortRowInfo;

        if (!srInfo) return;

        const shortRowTechnique = this.knittingOptions?.shortRowTechnique || 'wraps';
        const positionInfo = this.getAbsolutePosition(firstShortRow);
        
        // Analyze the entire short row sequence to find the turning point
        const allRows: { index: number; activeStitches: number; row: StitchRow }[] = [];
        for (let k = 0; k < srInfo.totalRowsInShortRow; k++) {
            if (startIndex + k < sectionRows.length) {
                const r = sectionRows[startIndex + k];
                if (r.shortRowInfo) {
                    const activeStitches = r.shortRowInfo.activeStitchesLeft + r.shortRowInfo.activeStitchesRight;
                    allRows.push({ index: k, activeStitches, row: r });
                }
            }
        }
        
        if (allRows.length === 0) return;
        
        // Find the turning point (minimum active stitches)
        let minActiveStitches = allRows[0].activeStitches;
        let turningPointIndex = 0;
        
        for (let i = 0; i < allRows.length; i++) {
            if (allRows[i].activeStitches < minActiveStitches) {
                minActiveStitches = allRows[i].activeStitches;
                turningPointIndex = i;
            }
        }
        
        const firstActiveStitches = allRows[0].activeStitches;
        const lastActiveStitches = allRows[allRows.length - 1].activeStitches;
        
        // Split into decrease and increase phases
        const decreaseRows = allRows.slice(0, turningPointIndex + 1);
        const increaseRows = allRows.slice(turningPointIndex + 1);
        
        // Generate DECREASE PHASE instruction (if there are decreasing rows)
        if (decreaseRows.length > 0) {
            const decreaseStartStitches = decreaseRows[0].activeStitches;
            const decreaseEndStitches = decreaseRows[decreaseRows.length - 1].activeStitches;
            
            let decreaseInstr = '';
            const firstDecreaseRow = decreaseRows[0].row;
            const lastDecreaseRow = decreaseRows[decreaseRows.length - 1].row;
            
            // HOLD instruction
            if (srInfo.heldStitchesLeft > 0 || srInfo.heldStitchesRight > 0) {
                decreaseInstr += 'HOLD: ';
                if (srInfo.heldStitchesLeft > 0) {
                    decreaseInstr += `${srInfo.heldStitchesLeft} stitch${srInfo.heldStitchesLeft > 1 ? 'es' : ''} left. `;
                }
                if (srInfo.heldStitchesRight > 0) {
                    decreaseInstr += `${srInfo.heldStitchesRight} stitch${srInfo.heldStitchesRight > 1 ? 'es' : ''} right. `;
                }
                decreaseInstr += '\n';
            }
            
            // KNIT instruction for decrease phase
            if (decreaseStartStitches === decreaseEndStitches) {
                decreaseInstr += `KNIT: ${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''} across ${decreaseStartStitches} stitches.`;
            } else {
                decreaseInstr += `KNIT: ${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''}, decreasing from ${decreaseStartStitches} to ${decreaseEndStitches} stitches.`;
            }
            
            decreaseInstr += `${
                shortRowTechnique === 'wraps' ? ' Wrap last stitch and turn each row.' :
                shortRowTechnique === 'gaps' ? ' Turn (leave a gap) each row.' :
                shortRowTechnique === 'german' ? ' German short row (slip, turn) each row.' : ''
            } (RC=${firstDecreaseRow.rowNumber}${lastDecreaseRow.rowNumber !== firstDecreaseRow.rowNumber ? '-' + lastDecreaseRow.rowNumber : ''})`;
            
            // Generate row-by-row instructions for decrease phase
            const decreaseRowInstructions: string[] = [];
            for (const { index, row } of decreaseRows) {
                const rowSrInfo = row.shortRowInfo;
                if (rowSrInfo) {
                    const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                    decreaseRowInstructions.push(`Row ${baseRowIndex + startIndex + index + 1} (Decrease ${index + 1}/${decreaseRows.length}): Knit ${rowActiveStitches} sts (${rowSrInfo.activeStitchesLeft}L + ${rowSrInfo.activeStitchesRight}R). (RC=${row.rowNumber})`);
                }
            }
            
            instructions.push({
                text: decreaseInstr.trim(),
                stepData: {
                    text: decreaseInstr.trim(),
                    startRowIndex: baseRowIndex + startIndex,
                    endRowIndex: baseRowIndex + startIndex + decreaseRows[decreaseRows.length - 1].index,
                    rowsInStep: decreaseRows.length,
                    absolutePositioning: positionInfo
                },
                rows: decreaseRowInstructions
            });
        }
        
        // Generate INCREASE PHASE instruction (if there are increasing rows)
        if (increaseRows.length > 0) {
            const increaseStartStitches = increaseRows[0].activeStitches;
            const increaseEndStitches = increaseRows[increaseRows.length - 1].activeStitches;
            
            let increaseInstr = '';
            const firstIncreaseRow = increaseRows[0].row;
            const lastIncreaseRow = increaseRows[increaseRows.length - 1].row;
            
            // PICK UP instruction
            increaseInstr += 'PICK UP: Bring held stitches back into work.\n';
            
            // KNIT instruction for increase phase
            if (increaseStartStitches === increaseEndStitches) {
                increaseInstr += `KNIT: ${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''} across ${increaseStartStitches} stitches.`;
            } else {
                increaseInstr += `KNIT: ${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''}, increasing from ${increaseStartStitches} to ${increaseEndStitches} stitches.`;
            }
            
            increaseInstr += ` Pick up wraps as you go. (RC=${firstIncreaseRow.rowNumber}${lastIncreaseRow.rowNumber !== firstIncreaseRow.rowNumber ? '-' + lastIncreaseRow.rowNumber : ''})`;
            
            // Generate row-by-row instructions for increase phase
            const increaseRowInstructions: string[] = [];
            for (const { index, row } of increaseRows) {
                const rowSrInfo = row.shortRowInfo;
                if (rowSrInfo) {
                    const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                    const relativeIndex = index - turningPointIndex - 1;
                    increaseRowInstructions.push(`Row ${baseRowIndex + startIndex + index + 1} (Increase ${relativeIndex + 1}/${increaseRows.length}): Knit ${rowActiveStitches} sts (${rowSrInfo.activeStitchesLeft}L + ${rowSrInfo.activeStitchesRight}R). Pick up wraps. (RC=${row.rowNumber})`);
                }
            }
            
            instructions.push({
                text: increaseInstr.trim(),
                stepData: {
                    text: increaseInstr.trim(),
                    startRowIndex: baseRowIndex + startIndex + increaseRows[0].index,
                    endRowIndex: baseRowIndex + startIndex + increaseRows[increaseRows.length - 1].index,
                    rowsInStep: increaseRows.length,
                    absolutePositioning: positionInfo
                },
                rows: increaseRowInstructions
            });
        }
    }

    /**
     * Generate instructions for multiple short row sections at the same base row (mirrored pairs)
     * Each section needs BOTH decrease and increase phases to complete the short row technique
     */
    private _generateMirroredShortRowInstructions(sectionRows: StitchRow[], startIndices: number[], baseRowIndex: number, instructions: KnittingInstruction[]): void {
        const shortRowTechnique = this.knittingOptions?.shortRowTechnique || 'wraps';
        
        // Collect and analyze each section to find decrease/increase phases
        // NOTE: The stitch plan generator currently creates sections that only go one direction,
        // but proper short row technique requires BOTH phases (decrease then increase)
        const sections = startIndices.map(startIdx => {
            const firstRow = sectionRows[startIdx];
            const srInfo = firstRow.shortRowInfo;
            if (!srInfo) return null;
            
            // Collect all rows in this section
            const allRows: { index: number; activeStitches: number; row: StitchRow }[] = [];
            for (let k = 0; k < srInfo.totalRowsInShortRow; k++) {
                if (startIdx + k < sectionRows.length) {
                    const r = sectionRows[startIdx + k];
                    if (r.shortRowInfo) {
                        const activeStitches = r.shortRowInfo.activeStitchesLeft + r.shortRowInfo.activeStitchesRight;
                        allRows.push({ index: k, activeStitches, row: r });
                    }
                }
            }
            
            // Find the turning point (minimum active stitches)
            let minActiveStitches = allRows[0]?.activeStitches || 0;
            let turningPointIndex = 0;
            
            for (let i = 0; i < allRows.length; i++) {
                if (allRows[i].activeStitches < minActiveStitches) {
                    minActiveStitches = allRows[i].activeStitches;
                    turningPointIndex = i;
                } else if (allRows[i].activeStitches === minActiveStitches) {
                    // If there are multiple rows at minimum, use the middle one
                    turningPointIndex = i;
                }
            }
            
            const firstActiveStitches = allRows[0]?.activeStitches || 0;
            const lastActiveStitches = allRows[allRows.length - 1]?.activeStitches || 0;
            const isRightSide = (srInfo.posX ?? 0.5) > 0.5;
            
            // Split into decrease and increase phases at the turning point
            const decreaseRows = allRows.slice(0, turningPointIndex + 1);
            const increaseRows = allRows.slice(turningPointIndex + 1);
            
            return {
                startIdx,
                srInfo,
                firstRow,
                allRows,
                decreaseRows,
                increaseRows,
                turningPointIndex,
                firstActiveStitches,
                lastActiveStitches,
                isRightSide,
                label: srInfo.shortRowLabel || (isRightSide ? 'right' : 'left')
            };
        }).filter(s => s !== null);
        
        if (sections.length === 0) return;
        
        // Generate instructions for each section: decrease phase followed by increase phase
        sections.forEach(section => {
            if (!section) return;
            
            const { startIdx, srInfo, label, decreaseRows, increaseRows } = section;
            
            // Generate DECREASE PHASE instruction
            if (decreaseRows.length > 0) {
                const decreaseStartStitches = decreaseRows[0].activeStitches;
                const decreaseEndStitches = decreaseRows[decreaseRows.length - 1].activeStitches;
                const firstDecreaseRow = decreaseRows[0].row;
                const lastDecreaseRow = decreaseRows[decreaseRows.length - 1].row;
                
                let decreaseInstr = `SHORT ROW SECTION (${label}) - DECREASE PHASE:\n\n`;
                
                // Hold instruction
                if (srInfo.heldStitchesLeft > 0 || srInfo.heldStitchesRight > 0) {
                    decreaseInstr += 'HOLD: ';
                    if (srInfo.heldStitchesLeft > 0) {
                        decreaseInstr += `${srInfo.heldStitchesLeft} stitch${srInfo.heldStitchesLeft > 1 ? 'es' : ''} left. `;
                    }
                    if (srInfo.heldStitchesRight > 0) {
                        decreaseInstr += `${srInfo.heldStitchesRight} stitch${srInfo.heldStitchesRight > 1 ? 'es' : ''} right. `;
                    }
                    decreaseInstr += '\n';
                }
                
                // Knit instruction
                decreaseInstr += 'KNIT: ';
                if (decreaseStartStitches === decreaseEndStitches) {
                    decreaseInstr += `${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''} across ${decreaseStartStitches} stitches. `;
                } else {
                    decreaseInstr += `${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''}, decreasing from ${decreaseStartStitches} to ${decreaseEndStitches} stitches. `;
                }
                
                decreaseInstr += `${
                    shortRowTechnique === 'wraps' ? 'Wrap last stitch and turn each row.' :
                    shortRowTechnique === 'gaps' ? 'Turn (leave a gap) each row.' :
                    shortRowTechnique === 'german' ? 'German short row (slip, turn) each row.' : ''
                } (RC=${firstDecreaseRow.rowNumber}${lastDecreaseRow.rowNumber !== firstDecreaseRow.rowNumber ? '-' + lastDecreaseRow.rowNumber : ''})`;
                
                // Add row-by-row instructions
                const decreaseRowInstructions: string[] = [];
                for (const { index, row } of decreaseRows) {
                    const rowSrInfo = row.shortRowInfo;
                    if (rowSrInfo) {
                        const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                        decreaseRowInstructions.push(`Row ${baseRowIndex + startIdx + index + 1} (${label}, Decrease ${index + 1}/${decreaseRows.length}): Knit ${rowActiveStitches} sts. (RC=${row.rowNumber})`);
                    }
                }
                
                const positionInfo = this.getAbsolutePosition(firstDecreaseRow);
                
                instructions.push({
                    text: decreaseInstr.trim(),
                    stepData: {
                        text: decreaseInstr.trim(),
                        startRowIndex: baseRowIndex + startIdx,
                        endRowIndex: baseRowIndex + startIdx + decreaseRows[decreaseRows.length - 1].index,
                        rowsInStep: decreaseRows.length,
                        absolutePositioning: positionInfo
                    },
                    rows: decreaseRowInstructions
                });
            }
            
            // Generate INCREASE PHASE instruction
            if (increaseRows.length > 0) {
                const increaseStartStitches = increaseRows[0].activeStitches;
                const increaseEndStitches = increaseRows[increaseRows.length - 1].activeStitches;
                const firstIncreaseRow = increaseRows[0].row;
                const lastIncreaseRow = increaseRows[increaseRows.length - 1].row;
                
                let increaseInstr = `SHORT ROW SECTION (${label}) - INCREASE PHASE:\n\n`;
                increaseInstr += 'PICK UP: Bring held stitches back into work.\n';
                increaseInstr += 'KNIT: ';
                
                if (increaseStartStitches === increaseEndStitches) {
                    increaseInstr += `${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''} across ${increaseStartStitches} stitches. `;
                } else {
                    increaseInstr += `${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''}, increasing from ${increaseStartStitches} to ${increaseEndStitches} stitches. `;
                }
                
                increaseInstr += `Pick up wraps as you go. (RC=${firstIncreaseRow.rowNumber}${lastIncreaseRow.rowNumber !== firstIncreaseRow.rowNumber ? '-' + lastIncreaseRow.rowNumber : ''})`;
                
                // Add row-by-row instructions
                const increaseRowInstructions: string[] = [];
                for (const { index, row } of increaseRows) {
                    const rowSrInfo = row.shortRowInfo;
                    if (rowSrInfo) {
                        const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                        increaseRowInstructions.push(`Row ${baseRowIndex + startIdx + index + 1} (${label}, Increase ${index + 1}/${increaseRows.length}): Knit ${rowActiveStitches} sts. Pick up wraps. (RC=${row.rowNumber})`);
                    }
                }
                
                const positionInfo = this.getAbsolutePosition(firstIncreaseRow);
                
                instructions.push({
                    text: increaseInstr.trim(),
                    stepData: {
                        text: increaseInstr.trim(),
                        startRowIndex: baseRowIndex + startIdx + increaseRows[0].index,
                        endRowIndex: baseRowIndex + startIdx + increaseRows[increaseRows.length - 1].index,
                        rowsInStep: increaseRows.length,
                        absolutePositioning: positionInfo
                    },
                    rows: increaseRowInstructions
                });
            }
        });
    }
    
    /**
     * Generate cable crossing instruction text
     * 
     * @param cable - Cable cross event
     * @returns Formatted cable instruction string
     */
    protected generateCableInstruction(cable: CableCrossEvent): string {
        const { leftGroup, rightGroup, middleGroup, direction, startIndex } = cable;
        
        if (middleGroup) {
            // Three-strand braid
            return `${leftGroup}x${middleGroup}x${rightGroup} braid at st ${startIndex + 1}`;
        }
        
        const totalStitches = leftGroup + rightGroup;
        const crossType = direction === 'L' ? 'front' : 'back';
        const cableNotation = `C${totalStitches}${direction === 'L' ? 'F' : 'B'}`;
        
        // Detailed instruction
        let instruction = `${cableNotation}: Slip ${leftGroup} sts to cable needle, hold to ${crossType}, `;
        instruction += `knit ${rightGroup} sts from left needle, `;
        instruction += `knit ${leftGroup} sts from cable needle`;
        
        return instruction;
    }
    
    /**
     * Get cable annotation for a row (compact format)
     * 
     * @param row - StitchRow with cable crosses
     * @returns Cable annotation string or empty string
     */
    protected getCableAnnotation(row: StitchRow): string {
        if (!row.cableCrosses || row.cableCrosses.length === 0) {
            return '';
        }
        
        const cableTexts = row.cableCrosses.map(cable => {
            const { leftGroup, rightGroup, direction, startIndex } = cable;
            const totalStitches = leftGroup + rightGroup + (cable.middleGroup || 0);
            const notation = `C${totalStitches}${direction === 'L' ? 'F' : 'B'}`;
            return `${notation}@${startIndex + 1}`;
        });
        
        return ` [${cableTexts.join(', ')}]`;
    }
}

export default HandKnittingActualizer;
